questionvariables.text:
/* correct answer */
corr_ans1:[[1, true, "Idempotent Law"]];
corr_ans2:[[7, true, "Distributive Law"]];
corr_ans3:[[8, true, "Commutative Law"]];

/* wrong answers */
incorr_ans: rand_selection([
[2, false, "Complement Law"],
[3, false, "Symmetric Difference Law"],
[4, false, "Associative Law"],
[5, false, "Absorption Law"],
[6, false, "De Morgan's Laws"]], 3);

ma1: random_permutation(append(corr_ans1, incorr_ans));
ma2: random_permutation(append(corr_ans2, incorr_ans));
ma3: random_permutation(append(corr_ans3, incorr_ans));

/*Worked Soln*/
question_test: rand([1,7,8]);
ma: if question_test=1 then ma1  elseif question_test =7 then ma2 else ma3;
ta_index: sort(makelist(x[1], x, ma));
